from itertools import product

def count_valid(n):
    count = 0
    for coloring in product(range(3), repeat=n):
        if len(set(coloring)) < 3:
            continue
        valid = True
        for s in range(3, 2*n):
            color_pairs = set()
            for i in range(1, (s+1)//2):
                j = s - i
                if j > n:
                    continue
                ci, cj = coloring[i-1], coloring[j-1]
                if ci != cj:
                    pair = (min(ci,cj), max(ci,cj))
                    color_pairs.add(pair)
                    if len(color_pairs) > 1:
                        valid = False
                        break
            if not valid:
                break
        if valid:
            count += 1
    return count

for n in range(3, 13):
    print(f"n={n}: {count_valid(n)}")
